{
  "factor_id": "hilo_pos_20d",
  "factor_name": "20-day range position (stochastic oscillator)",
  "version": "1.0.0",
  "calculation": {
    "expression": "(close - rolling_min(low,20)) / (rolling_max(high,20) - rolling_min(low,20))",
    "description": "Where today's close sits inside the trailing 20-day high-low range, normalized to [0,1]. Values near 1 mean the asset closes near its recent range high (short-term uptrend / strength); values near 0 mean it closes near the range low. Positive cross-sectional predictive power at 10-20d horizon indicates trend continuation of the range position, while 1-2d IC is negative (short-term reversal around the range edges)."
  },
  "dependencies": ["close", "high", "low"],
  "parameters": {
    "window": 20
  },
  "expected_direction": 1,
  "validation": {
    "status": "EFFECTIVE",
    "period": "2020-01-01..2026-07-15",
    "last_validated": "2026-07-30",
    "admission_horizon": 10,
    "regime_notes": "Validated 2020-01-01..2026-07-15 on the 15-asset cross-asset universe (equity indices, commodities, crypto, yield series) across multiple regimes: COVID crash 2020, recovery bull 2020-21, 2022 tightening bear, 2023-24 AI-led equity rally, 2024-26 crypto/commodity cycles. Daily cross-sectional Spearman IC, min 8 valid instruments per date.",
    "metrics": {
      "ic": 0.0318,
      "icir": 0.0973,
      "ic_hit_ratio": 0.542,
      "n_ic_dates": 1666,
      "coverage_asset_days": 0.7303,
      "coverage_dates_ge8": 0.7313,
      "turnover_10d_rank": 3.8004,
      "decay_ic_by_horizon": {
        "1": -0.0203,
        "2": -0.0122,
        "3": 0.0003,
        "5": 0.0114,
        "10": 0.0318,
        "20": 0.0377
      },
      "max_abs_library_correlation": 0.4171,
      "max_corr_library_id": "mom_10d_skip5"
    }
  },
  "tags": ["range-position", "trend", "cross-asset", "stochastic"],
  "benchmark_admission": {
    "contract": {
      "ic_threshold": 0.007,
      "icir_threshold": 0.084,
      "correlation_threshold": 0.5,
      "library_capacity": 30,
      "active_top_k": 10
    },
    "selected_metrics": {
      "ic": 0.0318,
      "icir": 0.0973,
      "metric_path": "validation.metrics",
      "max_abs_library_correlation": 0.4171,
      "correlation_path": "validation.metrics.max_abs_library_correlation"
    }
  }
}
